mapper.select:
select p.`ProjectID`, p.`ProjectName`, case when p.`Status` = 1 then '待审核' when p.`Status` = 2 then '待修改' when p.`Status` = 3 then '进行中' when p.`Status` = 4 then '待结项' when p.`Status` = 5 then '已归档' end as `ProjectStatus`, count(*) as `TotalTaskCount`, count(case when t.`Status` = 4 then 1 end) as `CompletedTaskCount`, case when count(*) > 0 then count(case when t.`Status` = 4 then 1 end) / count(*) * 100.0 else 0 end as `CompletedTaskPercent` from `Project` p left join `Task` t on p.`ProjectID` = t.`ProjectID`
t.`DevID` = #{userId}
p.`PMID` = #{userId}
and p.`ProjectID` in
#{projectId}
group by p.`ProjectID` order by `CompletedTaskPercent` desc

select dt.`TagName`, avg(perf.`Quality`) as `QualityAverage`, avg(perf.`Efficiency`) as `EfficiencyAverage`, avg(perf.`TotalScore`) as `TotalScoreAverage`, count(*) as `TaskCount` from `Task_Performance` perf left join `Tag_Relation` tr on perf.`TaskID` = tr.`TargetID` left join `Dict_Tag` dt on tr.`TagID` = dt.`TagID`
tr.`TargetType` = 2 and perf.`Status` = 2 and perf.`DevID` = #{devId}
and perf.`DevID` = #{currUserId}
group by dt.`TagID` order by `TotalScoreAverage`
